#' Paired Mean Comparison (Python)
#'
#' 
#' @param data .
#' @param dep1 .
#' @param dep2 .
#' @param subject .
#' @param conflevel .
#' @param showCases .
#' @param showPlot .
#' @param showStandardized .
#' @param showConsole .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$summary} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$cohort} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$missing} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$descriptives} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$contrast} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$cases} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$differencePlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$standardizer} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$standardized} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$hedges} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$standardizedPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$console} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$cohort$asDF}
#'
#' \code{as.data.frame(results$cohort)}
#'
#' @export
pyjjwithinstats <- function(
    data,
    dep1 = NULL,
    dep2 = NULL,
    subject = NULL,
    conflevel = 0.95,
    showCases = FALSE,
    showPlot = TRUE,
    showStandardized = FALSE,
    showConsole = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("pyjjwithinstats requires jmvcore to be installed (restart may be required)")

    if ( ! missing(dep1)) dep1 <- jmvcore::resolveQuo(jmvcore::enquo(dep1))
    if ( ! missing(dep2)) dep2 <- jmvcore::resolveQuo(jmvcore::enquo(dep2))
    if ( ! missing(subject)) subject <- jmvcore::resolveQuo(jmvcore::enquo(subject))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(dep1), dep1, NULL),
            `if`( ! missing(dep2), dep2, NULL),
            `if`( ! missing(subject), subject, NULL))


    options <- pyjjwithinstatsOptions$new(
        dep1 = dep1,
        dep2 = dep2,
        subject = subject,
        conflevel = conflevel,
        showCases = showCases,
        showPlot = showPlot,
        showStandardized = showStandardized,
        showConsole = showConsole)

    analysis <- pyjjwithinstatsClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

